        return levelForPoints(membershipPoints(owner, householdMemberCount));
    }

    private static Integer levelForPoints(int points) {
        if (points >= 6) {
            return 4;
        }
        if (points >= 4) {
            return 3;
        }
        if (points >= 2) {
            return 2;
        }
        return 1;
    }

